#!/usr/bin/env node
/** BB-000518: CI guard — OpenAPI snapshot must exist (generated by backend spectacular step). */
import { access } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const snapshot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../docs/openapi-snapshot.json',
);

try {
  await access(snapshot);
  console.log(`OpenAPI snapshot present: ${snapshot}`);
} catch {
  console.error(`Missing OpenAPI snapshot at ${snapshot}`);
  process.exit(1);
}
